{
  "items": [
    {
      "path": "tools.team_message",
      "description": "Send a message to a specific teammate or to the lead. Use 'lead' to message the team lead. Lead only: pass 'model' (provider/model) to update a teammate's model in-place.",
      "signature": "tools.team_message({
  /** Recipient name ('lead' or teammate name) */
  to: string,
  /** Message content (max 10KB). Optional only when 'model' is provided. */
  text?: string,
  /** Approve a teammate's plan (only when recipient has plan_approval='pending'). @default false */
  approve?: boolean,
  /** Reject a teammate's plan with reason (only when recipient has plan_approval='pending') */
  reject?: string,
  /** Lead only. Re-activate a teammate who already reported task completion. @default false */
  force?: boolean,
  /** Lead only: update the recipient teammate's model in-place, in 'provider/model' format. */
  model?: string,
  /**
   * Lead only, to=lead: update the shared worker budget without interrupting running work. Text is optional for scheduling updates.
   * @integer @minimum 0
   */
  max_running_members?: number,
  /**
   * Lead only, to=lead: persist provider preference locally for this mission. Empty array restores default routing. Separate call from other controls; text optional.
   * @maxItems 64
   */
  provider_order?: Array<string>,
  /** Revision read from team_status; rejects stale provider-order edits. @integer @minimum 0 */
  provider_order_revision?: number,
  /**
   * Durable model/effort preference. Balanced mode uses a shrinking quality window and weighted distribution; reserve models run only when ordinary candidates are insufficient. Separate lead-only update; null restores project inheritance.
   */
  model_policy?: {
      mode: "legacy" | "balanced",
      /**
       * Cost tie-break basis; effective costs never fall back to API benchmarks or estimates. Amortized uses explicit subscription-allocated AA task estimates, not measured billing.
       */
      costMode?: "legacy" | "benchmark" | "effective" | "amortized",
      /** @minimum 0 @maximum 10 */
      maxIntelligenceGap: number,
      /** @maxItems 128 */
      models: Array<{
          /** Exact evaluated provider/model ID */
          id: string,
          /** Exact evaluated native reasoning variant; omitted means default */
          reasoningEffort?: string,
          /** Independent traffic weight; zero excludes automatic selection. @integer @minimum 0 @maximum 100 */
          preference?: number,
          enabled?: boolean,
          reserve?: boolean,
        }>,
    } | null,
  /** Model policy revision read from team_status; rejects stale edits. @integer @minimum 0 */
  model_policy_revision?: number,
  /** Lead only, to=lead: enable or disable deterministic assignment. */
  auto_dispatch?: boolean,
  /** Lead only, to=lead: enable or disable automatic worker creation. */
  auto_scale?: boolean,
  /** Frozen mission classification defaults/explicit overrides */
  classification?: {
    mode?: "off" | "auto" | "jev" | "general" | "x86",
    /** Explicit helper model in provider/model format; no model is chosen implicitly */
    helperModel?: string,
    /** Native reasoning variant for the helper model */
    helperVariant?: string,
    /** Exact classifier tool ID; empty means discover the known JEV contract */
    toolId?: string,
    /** @integer @minimum 1 */
    timeoutMs?: number,
    missionMode?: "supervised" | "long_run",
    /** Explicit model for embedded general classification; never activated automatically */
    generalModel?: string,
    /** Reasoning variant for the general classifier */
    generalVariant?: string,
    /** In auto mode, prefer the discovered x86 tool for explicit x86 tasks */
    specialized?: boolean,
    /** Exact specialized tool ID; empty discovers the known classify_x86 contract */
    x86ToolId?: string,
    /** @maxItems 8 */
    fallbacks?: Array<{
        method: "jev" | "general",
        /** Explicitly authorized classifier/helper model */
        model: string,
        /** Reasoning variant */
        variant?: string,
        /** Exact JEV tool ID */
        toolId?: string,
      }>,
    limits?: {
      /** @integer @minimum 0 */
      retries?: number,
      /** @integer @minimum 0 */
      retryDelayMs?: number,
      /** @integer @minimum 1 */
      maxAttempts?: number,
      /** @integer @minimum 1 */
      maxCalls?: number,
      /** @integer @minimum 1 */
      maxDurationMs?: number,
      /** @integer @minimum 1 */
      maxInputBytes?: number,
      /** @integer @minimum 1 */
      concurrency?: number,
      /** @integer @minimum 1 */
      circuitThreshold?: number,
      /** @integer @minimum 1 */
      circuitCooldownMs?: number,
      /** @integer @minimum 0 */
      maxCircuitRechecks?: number,
    },
  },
}): Promise<string | null>"
    }
  ],
  "remaining": 0,
  "next": null
}

{
  "items": [
    {
      "path": "tools["context-mode"].ctx_batch_execute",
      "description": "Run multiple commands in ONE call. Every command's output is auto-indexed into the knowledge base; if you also pass `queries`, the matching sections come back in the same round trip so a follow-up search call is not needed.

Concurrency parallelizes the FETCH phase (run-the-commands). The DERIVATION phase — turning raw output into an answer — still belongs in code: add a processing command that consumes the indexed output and prints only the answer, so the raw bytes never enter your conversation (Think-in-Code, same principle as the sandbox tool).

WHEN:
  - You have 3+ related commands you would otherwise run sequentially (multi-issue lookups, git log + git diff + git blame, multi-file reads, multi-region cloud queries)
  - You want to gather AND query in one round trip — pass `queries` so the matching sections come back inline
  - You want to parallelize I/O-bound work — pass `concurrency` 2-8 (network calls, gh CLI, cloud APIs, multi-repo git reads)
  - The combined output is large enough that piping it through ctx_search later would itself be expensive — let auto-index + inline queries do both in one shot

WHEN NOT:
  - Single command with no follow-up query — run it in the sandbox tool directly
  - CPU-bound or stateful commands — keep concurrency at 1 (npm test, build, lint, port-binding servers, lock-file holders, anything that races on the same resource)

RETURNS:
  Auto-indexed section list per command label, plus top matches per query (when `queries` is passed). Raw output is NOT echoed in full — only the matched windows. Concurrency>1 switches each command to its own per-command timeout (no shared budget); concurrency=1 preserves the legacy shared-budget cascading-skip-on-timeout path. Use 4-8 for I/O-bound batches; keep at 1 for CPU work or shared-state commands; lower the value when target hosts enforce per-IP rate limits.

EXAMPLE: ctx_batch_execute(
  commands: [
    {label: "issue 1", command: "gh issue view 1"},
    {label: "issue 2", command: "gh issue view 2"},
    {label: "summarize", command: "echo done"}
  ],
  queries: ["root cause", "proposed fix"],
  concurrency: 2
)",
      "signature": "tools["context-mode"].ctx_batch_execute({
  /**
   * Commands to execute as a batch. Output is labeled with the section header. Default order is sequential; pass concurrency>1 to run in parallel (output stays in input order).
   * @minItems 1
   */
  commands: Array<{
      /** Section header for this command's output (e.g., 'README', 'Package.json', 'Source Tree') */
      label: string,
      /** Shell command to execute */
      command: string,
    }>,
  /**
   * Search queries to extract information from indexed output. Use 5-8 comprehensive queries. Each returns top 5 matching sections with full content. This is your ONLY chance — put ALL your questions here. No follow-up calls needed.
   * @minItems 1
   */
  queries: Array<string>,
  /**
   * Max execution time in ms. When omitted, no server-side timer fires — the MCP host's RPC timeout governs. With concurrency=1, the value (when set) is a shared budget across commands; with concurrency>1, it is applied per-command.
   */
  timeout?: number,
  /**
   * Max commands to run in parallel (1-8, default: 1). Use 4-8 for I/O-bound batches (network, gh, curl, multi-repo git reads). Keep at 1 for CPU-bound (npm test, build, lint) or stateful commands (ports, locks). >1 switches to per-command timeouts (no shared budget) and individual `(timed out)` blocks instead of cascading skip.
   * @default 1 @integer @minimum 1 @maximum 8
   */
  concurrency?: number,
  /** Optional working directory for all shell commands in this batch. */
  cwd?: string,
  /**
   * Scope for `queries` (default: `batch`). `batch` searches ONLY the chunks produced by this batch's commands — useful when you want answers about the just-fetched output. `global` searches the entire persistent index (same scope as ctx_search) — useful when you want the batch commands to enrich context and the queries to also surface related prior knowledge in one round trip.
   * @default "batch"
   */
  query_scope?: "batch" | "global",
}): Promise<unknown>"
    },
    {
      "path": "tools["context-mode"].ctx_execute",
      "description": "Run code in a sandboxed subprocess. (Bun detected — JS/TS runs 3-5x faster) Languages: javascript, shell, typescript, python, rust.

Think-in-Code — the core philosophy: the bytes your code processes never enter your conversation memory; only what you console.log() does. Reading a 700 KB log directly means 700 KB of your remaining reasoning capacity gets spent on raw bytes. Running code over that same log in this sandbox and printing a 3 KB summary leaves you with 697 KB of capacity for the actual work.

Concrete shape — analyze 47 source files without reading any of them:
  ctx_execute(language: "javascript", code: `
    const fs = require('fs');
    const files = fs.readdirSync('src').filter(f => f.endsWith('.ts'));
    files.forEach(f => {
      const lines = fs.readFileSync('src/'+f,'utf8').split('\\n').length;
      console.log(f + ': ' + lines + ' lines');
    });
  `)
  // 47 files analyzed, 15,314 LoC summarized — output ~3.6 KB instead of 47 Read() calls = ~700 KB.

WHEN:
  - You intend to derive an answer FROM data (filter, count, aggregate, parse, compare, transform) — do the derivation in code and print only the answer
  - Output shape or size cannot be predicted before execution (recursive finds, repo-wide greps, list endpoints, query results, log scans)
  - You would otherwise read raw output and then mentally compute — that compute belongs here, in code, where its inputs stay out of your conversation
  - You need to keep a long-running process alive (dev server, watcher, daemon) — pass `background: true` to detach on timeout instead of killing the process
  - The output may legitimately be large but you only want recall-by-topic later — pass an `intent` string; outputs over ~5KB are auto-indexed into the knowledge base and only the section titles + previews come back, retrievable via ctx_search

WHEN NOT:
  - Single observational command whose entire short output you intend to consume verbatim (whoami, pwd, git status on a clean tree) — Bash is simpler
  - File mutations (Edit/Write) or navigation (cd/ls) — Bash is the right surface
  - You already know the output is one short fixed line and you want to read it as-is

RETURNS:
  Only what your code prints. Wrap risky calls in try/catch — uncaught errors go to stderr and may leak more than intended. When `intent` is set and output exceeds the auto-index threshold, the response carries searchable section titles + previews instead of the raw stdout; use ctx_search(queries: [...]) to drill into specific sections.

EXAMPLE: ctx_execute(language: "javascript", code: "const out = require('child_process').execSync('npm test', {encoding:'utf8', stdio:['ignore','pipe','pipe']}); console.log(out.split('\\n').filter(l => /(FAIL|✗|×|Error:|Tests +.*(failed|passed))/i.test(l)).slice(0, 60).join('\\n'))")
EXAMPLE: ctx_execute(language: "javascript", code: "const out = require('child_process').execSync('gh issue list --json number,title --limit 100', {encoding:'utf8'}); const hooks = JSON.parse(out).filter(i => /hook|routing/i.test(i.title)); console.log(`${hooks.length} hook-related issues`)")",
      "signature": "tools["context-mode"].ctx_execute({
  /** Runtime language */
  language: "javascript" | "typescript" | "python" | "shell" | "ruby" | "go" | "rust" | "php" | "perl" | "r" | "elixir" | "csharp",
  /**
   * Source code to execute. Use console.log (JS/TS), print (Python/Ruby/Perl/R), echo (Shell), echo (PHP), fmt.Println (Go), IO.puts (Elixir), or Console.WriteLine (C#) to output a summary to context.
   */
  code: string,
  /**
   * Max execution time in ms. When omitted, no server-side timer fires — the MCP host's RPC timeout governs (which is the right layer for this policy). Pass an explicit value for long-running builds (Gradle/Maven/SBT).
   */
  timeout?: number,
  /**
   * Keep process running after timeout (for servers/daemons). Returns partial output without killing the process. IMPORTANT: Do NOT add setTimeout/self-close timers in background scripts — the process must stay alive until the timeout detaches it. For server+fetch patterns, prefer putting both server and fetch in ONE ctx_execute call instead of using background.
   * @default false
   */
  background?: boolean,
  /**
   * Optional working directory for shell commands. Non-shell languages still execute from their sandbox temp directory.
   */
  cwd?: string,
  /**
   * What you're looking for in the output. When provided and output is large (>5KB), indexes output into knowledge base and returns section titles + previews — not full content. Use ctx_search(queries: [...]) to retrieve specific sections. Example: 'failing tests', 'HTTP 500 errors'.
   *
   * TIP: Use specific technical terms, not just concepts. Check 'Searchable terms' in the response for available vocabulary.
   */
  intent?: string,
}): Promise<unknown>"
    }
  ],
  "remaining": 9,
  "next": {
    "offset": 2
  }
}

